add_filter( 'woocommerce_package_rates', 'perfectpixel_only_free_shipping_when_available', 100 );

function perfectpixel_only_free_shipping_when_available( $rates ) {
	$keep = array();
	foreach ( $rates as $rate_id => $rate ) {
		if ( 'free_shipping' === $rate->get_method_id() ) {
			$keep[ $rate_id ] = $rate;
		}
	}
	if ( ! $keep ) {
		return $rates;
	}
	if ( 'yes' === '{{keep_local_pickup}}' ) {
		foreach ( $rates as $rate_id => $rate ) {
			if ( in_array( $rate->get_method_id(), array( 'local_pickup', 'pickup_location' ), true ) ) {
				$keep[ $rate_id ] = $rate;
			}
		}
	}
	return $keep;
}
